import{at as e,it as t,n,vt as r}from"./chunks/framework.DkF-bNzI.js";var i=JSON.parse(`{"title":"Fork survey","description":"","frontmatter":{},"headers":[],"relativePath":"forks.md","filePath":"forks.md","lastUpdated":1795530892000}`),a={name:`forks.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="fork-survey" tabindex="-1">Fork survey <a class="header-anchor" href="#fork-survey" aria-label="Permalink to “Fork survey”">​</a></h1><p>Survey of the public forks of <a href="https://github.com/sta-szek/pojo-tester" target="_blank" rel="noreferrer">sta-szek/pojo-tester</a>, taken on 23 November 2026. Nothing on this page was merged as a repository. It records what the forks added and what is already here.</p><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to “Verdict”">​</a></h2><p>Do not merge any fork back as a whole.</p><p>The only fork with a long independent history is <a href="https://github.com/obsidiandynamics/pojo-tester" target="_blank" rel="noreferrer">obsidiandynamics/pojo-tester</a>. It republishes the library under different Maven coordinates, stops writing <code>final</code> fields, and describes this project as abandoned. Taking that history would drop the Java 8 through 25 line. The behaviour worth keeping from the other forks is already on <code>master</code>.</p><h2 id="how-they-were-compared" tabindex="-1">How they were compared <a class="header-anchor" href="#how-they-were-compared" aria-label="Permalink to “How they were compared”">​</a></h2><p>The GitHub counter said 24 forks. The forks API returned 23 public repositories. Each default branch was compared with <code>master</code> (<code>base...fork:master</code>: commits reachable from the fork and not from <code>master</code>). Branches other than <code>master</code>, <code>gh-pages</code> and <code>issue-217</code> were compared the same way. <code>gh-pages</code> is the published site. <code>issue-217</code> on those forks is the 2017 supplier draft. The current form of that idea landed later, not as a fork.</p><p><code>ahead</code> means commits on the fork that are not in <code>master</code>. A feature can still already be present if it landed later as a different commit.</p><h2 id="already-in-this-repository" tabindex="-1">Already in this repository <a class="header-anchor" href="#already-in-this-repository" aria-label="Permalink to “Already in this repository”">​</a></h2><table tabindex="0"><thead><tr><th>Fork work</th><th>Where it landed</th></tr></thead><tbody><tr><td>User-defined instantiators (Galeries Lafayette and frecco75, 2020)</td><td>#243, <code>UserObjectInstantiator</code></td></tr><tr><td>Skip setters of <code>final</code> fields</td><td><code>SetterTester</code> filters with <code>FieldUtils.isFinal</code></td></tr><tr><td><code>toString</code> of primitive arrays</td><td>#231</td></tr><tr><td>Fast equals and hashCode, later <code>quickly()</code></td><td><code>AbstractAssertion.quickly()</code></td></tr><tr><td>Test every class in a package</td><td><code>assertPojoMethodsForAll(PackageFilter)</code></td></tr><tr><td>Static nested class</td><td>already in history</td></tr><tr><td>Bintray and Maven Central wiring</td><td>superseded by Central Portal publishing</td></tr><tr><td>Equals and hashCode of inner classes</td><td>#244</td></tr><tr><td>LGPL-3.0 text</td><td><code>LICENSE.MD</code></td></tr><tr><td><code>Method.getTester()</code> no longer calls <code>Class.newInstance()</code></td><td><code>getDeclaredConstructor().newInstance()</code></td></tr></tbody></table><h2 id="forks-with-nothing-of-their-own" tabindex="-1">Forks with nothing of their own <a class="header-anchor" href="#forks-with-nothing-of-their-own" aria-label="Permalink to “Forks with nothing of their own”">​</a></h2><p>These 18 default branches are strictly behind <code>master</code>.</p><p><code>sdk2035</code>, <code>djn72</code>, <code>p91paul</code>, <code>drobins29</code>, <code>thePrincipal</code> (default branch only), <code>niklasga</code>, <code>dhaase</code>, <code>rmohta</code>, <code>elvisnovoa</code>, <code>Theosakamg</code>, <code>anand1velusamy</code>, <code>jbaltus</code>, <code>gedl</code>, <code>adamsiemion</code>, <code>SemionPar</code>, <code>suteerth</code>, <code>theangrydev</code>, <code>waffle-iron</code>.</p><h2 id="forks-that-diverged" tabindex="-1">Forks that diverged <a class="header-anchor" href="#forks-that-diverged" aria-label="Permalink to “Forks that diverged”">​</a></h2><h3 id="obsidiandynamics-pojo-tester" tabindex="-1">obsidiandynamics/pojo-tester <a class="header-anchor" href="#obsidiandynamics-pojo-tester" aria-label="Permalink to “obsidiandynamics/pojo-tester”">​</a></h3><p>32 commits ahead, 18 behind. Last push 26 July 2022. Published as <code>com.obsidiandynamics.pojotester:core</code>. One downstream fork, <a href="https://github.com/sansp00/pojo-tester" target="_blank" rel="noreferrer">sansp00/pojo-tester</a>, which adds a Maven POM for those coordinates.</p><p>The library changes are array <code>toString</code>, skipping setters of <code>final</code> fields, and no longer clearing the <code>final</code> modifier. The first two are on <code>master</code>. The third deletes an ability this repository kept as <code>changingFinalFields()</code>. The rest is packaging from that period and documentation that calls this project abandoned.</p><p>Do not merge the repository. The coordinates and the decision about <code>final</code> fields conflict with this one.</p><h3 id="galeries-lafayette-pojo-tester" tabindex="-1">galeries-lafayette/pojo-tester <a class="header-anchor" href="#galeries-lafayette-pojo-tester" aria-label="Permalink to “galeries-lafayette/pojo-tester”">​</a></h3><p>7 commits ahead, 18 behind. January 2020. Released by them as <code>0.8.0</code> from a Maven build aimed at Java 12.</p><p>The library commits are custom instantiators, skipping setters on <code>final</code> fields, and a <code>FieldUtils</code> that stops writing <code>final</code> fields. The first two are on <code>master</code>. The third is the same deletion as the Obsidian change. This repository stays on Gradle.</p><h3 id="frecco75-pojo-tester" tabindex="-1">frecco75/pojo-tester <a class="header-anchor" href="#frecco75-pojo-tester" aria-label="Permalink to “frecco75/pojo-tester”">​</a></h3><p>5 commits ahead, 18 behind. The same series as Galeries Lafayette, with Java 13 instead of the Maven release commits. The instantiator and inner-class branches are already in history through #243 and #244.</p><h3 id="thecrazzymouse-pojo-tester-and-theprincipal-feature-java-13-compatible" tabindex="-1">thecrazzymouse/pojo-tester and thePrincipal <code>feature/java-13-compatible</code> <a class="header-anchor" href="#thecrazzymouse-pojo-tester-and-theprincipal-feature-java-13-compatible" aria-label="Permalink to “thecrazzymouse/pojo-tester and thePrincipal feature/java-13-compatible”">​</a></h3><p>One commit each, November 2019. Both stop clearing the <code>final</code> modifier. Superseded by the current <code>FieldUtils</code>.</p><h3 id="deleted-account-fast-test-equals-v2" tabindex="-1">Deleted account, <code>fast-test-equals-v2</code> <a class="header-anchor" href="#deleted-account-fast-test-equals-v2" aria-label="Permalink to “Deleted account, fast-test-equals-v2”">​</a></h3><p>The owner is shown as <code>36893488147419103231</code> because the account was deleted. That branch added <code>EQUALS_FAST</code> and <code>HASH_CODE_FAST</code>, then replaced them with <code>quickly()</code> after review on issue #203. <code>quickly()</code> is on <code>master</code>. Merging the branch would move the permutators and restore the abandoned enum constants.</p><h2 id="what-is-left" tabindex="-1">What is left <a class="header-anchor" href="#what-is-left" aria-label="Permalink to “What is left”">​</a></h2><p>Nothing from the forks is a missing feature.</p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};